-- Every application access assertion runs as anon/authenticated, not postgres.
SET ROLE anon;
SELECT public.test_denied('SELECT * FROM public.tracker_records','anon read denied');
SELECT public.test_denied('SELECT * FROM public.tracker_settings','anon settings denied');
SELECT public.test_denied('SELECT * FROM public.tracker_changes','anon changes denied');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,'{}',false)$q$,'anon RPC denied');
RESET ROLE;
SET ROLE authenticated;
SELECT public.test_denied($q$SELECT public.tracker_apply_change('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,'{}',false)$q$,'missing identity RPC denied');
SELECT set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
SELECT set_config('test.entry',$j${"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","kind":"symptom","occurredAt":"2026-10-19T00:00:00.000Z","createdAt":"2026-10-20T00:00:00.000Z","updatedAt":"2026-10-20T00:00:00.000Z","estimatedTime":true,"deletedAt":null,"note":"synthetic","discomfort":{"status":"unknown","symptoms":[]},"context":""}$j$,false);
SELECT set_config('test.settings',$j${"meals":{"breakfast":{"time":"08:00","enabled":true},"lunch":{"time":"12:00","enabled":true},"dinner":{"time":"18:00","enabled":false}},"foodTemplates":[],"snoozes":{},"remindersEnabled":false}$j$,false);
SELECT public.test_assert(public.tracker_apply_change('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,current_setting('test.entry')::jsonb,false)->>'status'='applied','first entry inserts base 0');
SELECT public.test_assert((public.tracker_apply_change('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,('{"note":"synthetic"}'::jsonb||(current_setting('test.entry')::jsonb-'note')),false)->'remote'->>'version')::int=1,'same change ID retry and JSON key order equality');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_changes)=1,'retry does not duplicate log');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,jsonb_set(current_setting('test.entry')::jsonb,'{note}','"different"'),false)$q$,'reused change ID different payload rejected','22023');
SELECT public.test_assert(public.tracker_apply_change('cccccccc-cccc-4ccc-8ccc-cccccccccccc','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,current_setting('test.entry')::jsonb,false)->>'status'='conflict','concurrent absent-row insert reports version conflict');
SELECT public.test_assert((public.tracker_apply_change('dddddddd-dddd-4ddd-8ddd-dddddddddddd','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,jsonb_set(current_setting('test.entry')::jsonb,'{deletedAt}','"2026-10-20T01:00:00.000Z"'),true)->'remote'->>'version')::int=2,'tombstone version increments');
SELECT public.test_assert((public.tracker_apply_change('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,current_setting('test.entry')::jsonb,false)->'remote'->>'tombstone')::boolean,'old device cannot resurrect tombstone');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_records WHERE tombstone)=1,'tombstone retained');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_changes)=2,'conflicts do not append changes');
SELECT public.test_assert((public.tracker_apply_change('ffffffff-ffff-4fff-8fff-ffffffffffff','settings','settings',0,current_setting('test.settings')::jsonb,false)->'remote'->>'version')::int=1,'settings independent version 1');
SELECT public.test_assert(public.tracker_apply_change('00000000-0000-4000-8000-000000000001','settings','settings',0,current_setting('test.settings')::jsonb,false)->>'status'='conflict','settings version conflict');
SELECT public.test_assert((public.tracker_apply_change('00000000-0000-4000-8000-000000000002','settings','settings',1,jsonb_set(current_setting('test.settings')::jsonb,'{foodTemplates}','["synthetic"]'),false)->'remote'->>'version')::int=2,'settings retry version 2');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('00000000-0000-4000-8000-000000000003','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,current_setting('test.entry')::jsonb||'{"owner_id":"22222222-2222-4222-8222-222222222222"}',false)$q$,'payload owner spoof rejected','22023');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('00000000-0000-4000-8000-000000000004','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,'{}',false)$q$,'malformed JSON rejected','22023');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('00000000-0000-4000-8000-000000000006','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,jsonb_set(current_setting('test.entry')::jsonb,'{discomfort,status}','null'),false)$q$,'null enum rejected','22023');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('00000000-0000-4000-8000-000000000007','settings','wrong-id',0,current_setting('test.settings')::jsonb,false)$q$,'settings fixed id enforced','22023');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('00000000-0000-4000-8000-000000000008','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',-1,current_setting('test.entry')::jsonb,false)$q$,'negative version rejected','22023');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('00000000-0000-4000-8000-000000000009','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,current_setting('test.entry')::jsonb,true)$q$,'inconsistent tombstone rejected','22023');
SELECT public.test_denied('SELECT * FROM public.tracker_change_ledger','ledger private');
SELECT public.test_denied($q$INSERT INTO public.tracker_records(owner_id,id,version,snapshot,tombstone,occurred_at) VALUES('22222222-2222-4222-8222-222222222222','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'{}',false,now())$q$,'direct cross-owner insert denied');
SELECT public.test_denied('UPDATE public.tracker_records SET version=99','direct update denied');
SELECT public.test_denied('DELETE FROM public.tracker_records','direct delete denied');
SELECT public.test_denied('UPDATE public.tracker_settings SET version=99','direct settings update denied');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_changes WHERE seq>0)=4,'first pull from cursor zero includes full history');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_changes WHERE seq>(SELECT min(seq) FROM public.tracker_changes))=3,'strict seq cursor excludes boundary');
SELECT current_user AS assertion_role,count(*) AS own_log_count FROM public.tracker_changes;
SELECT set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',false);
SELECT public.test_assert((SELECT count(*) FROM public.tracker_records)=0,'user B cannot read A entries');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_settings)=0,'user B cannot read A settings');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_changes)=0,'user B cannot read A logs');
SELECT public.test_denied($q$SELECT public.tracker_apply_change('00000000-0000-4000-8000-000000000005','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,current_setting('test.entry')::jsonb,false)$q$,'cross-user RPC cannot update A version','22023');
SELECT public.test_assert((public.tracker_apply_change('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','entry','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,current_setting('test.entry')::jsonb,false)->'remote'->>'version')::int=1,'same resource and change IDs isolated by owner');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_records)=1,'B sees own row only');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_changes)=1,'B sees own log only');
SELECT current_user AS assertion_role,count(*) AS own_log_count FROM public.tracker_changes;
SELECT set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
SELECT public.test_assert((SELECT version FROM public.tracker_records WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')=2,'B RPC did not alter A tombstone');
SELECT public.test_assert((SELECT count(*) FROM public.tracker_changes)=4,'A logs remain isolated');
RESET ROLE;
